<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {Button,NativeSelect,Dialog,Tabs,useHostContext} from '@openclaw-plugins/control-ui-kit';
import {currentUiTarget,canOpenWorkerProject,openWorkerProject,subscribeWorkerNavigation} from '../../agent-repo-api/ui-navigation.mjs';
import {useManagementRequest} from './management-request';
import {type ProjectCatalog,type ProjectDetail} from './projects-model';
import type {AuditPage} from './audit-model';
import SkillMaintenance from './SkillMaintenance.vue';
import SubagentsView from './SubagentsView.vue';
import WorkspacePool from './WorkspacePool.vue';
import TaskDirectory from './TaskDirectory.vue';
import ScheduleManager from './ScheduleManager.vue';
import LogsView from './LogsView.vue';
import PeopleDialog from './PeopleDialog.vue';
import AuditView from './AuditView.vue';
import {date} from './task-directory-model';
const props=defineProps<{agentId?:string;mode?:string}>();
const context=useHostContext(),root=ref<HTMLElement>(),scroll=ref<HTMLElement>(),maintenance=ref<InstanceType<typeof SkillMaintenance>>();
const target=computed(()=>currentUiTarget({...context.value,props:{...context.value.props,agentId:props.agentId??context.value.props.agentId}}));
const agentId=computed(()=>target.value.agentId??''),mode=computed(()=>props.mode??context.value.props.managementSection??'');
const request=useManagementRequest(context,()=>agentId.value,'agent-repo','projects-',()=>mode.value?'agent:'+agentId.value+':agent-repo-management':target.value.sessionKey??'agent:'+agentId.value+':agent-repo-catalog');
const catalog=ref<ProjectCatalog>(),detail=ref<ProjectDetail>(),projectId=ref(''),repository=ref(''),query=ref(''),error=ref(''),loading=ref(false),skillView=ref('skills'),navigationAvailable=ref(canOpenWorkerProject()),logs=ref(false),people=ref(false),audit=ref(false),manager=ref<{id?:string;action?:string;sequence:number}>();
const scope=computed(()=>[agentId.value,mode.value,mode.value?'':target.value.sessionKey,context.value.host.connection.canRead,context.value.host.connection.canWrite,context.value.presented].join('|'));
const sources=computed(()=>projectId.value?(detail.value?.sources??[]).filter(s=>s.source!=='agent'):catalog.value?.agentSkills?[catalog.value.agentSkills]:[]);
const subagentSources=computed(()=>projectId.value?(detail.value?.subagentSources??[]).filter(s=>s.source!=='agent'):catalog.value?.agentSubagents?[catalog.value.agentSubagents]:[]);
const inherited=computed(()=>detail.value?.sources.find(s=>s.source==='agent')),inheritedSubagents=computed(()=>detail.value?.subagentSources?.find(s=>s.source==='agent'));
const tabs=computed(()=>[{id:'',label:'Agent Repo'},...(catalog.value?.projects??[]).map(p=>({id:p.projectId,label:context.value.host.redact(p.name)}))]);
const safe=(v:unknown)=>context.value.host.redact(String(v??''));
const sourceIsGroup=()=>/^agent:[^:]+:feishu:group:oc_/.test(target.value.sessionKey??'');
let generation=0,managerSequence=0,managerOrigin:string|undefined;
let lastRefreshContext:typeof context.value|undefined;
async function refresh(scanList=true){if(!context.value.presented||!context.value.host.connection.canRead||!agentId.value)return;lastRefreshContext=context.value;const token=++generation,valid=request.capture();loading.value=true;error.value='';if(scanList)void maintenance.value?.refresh();try{if(scanList||!catalog.value){const next=await request.invoke<ProjectCatalog>('list',{});if(!valid()||token!==generation)return;catalog.value={...next,projects:[...(next.projects??[])],...(next.scheduledTasks?{scheduledTasks:[...next.scheduledTasks]}:{})};}
 if(projectId.value&&!catalog.value!.projects.some(p=>p.projectId===projectId.value)){projectId.value='';repository.value='';detail.value=undefined;}
 const next=projectId.value?await request.invoke<ProjectDetail>('detail',{projectId:projectId.value,...(repository.value?{repository:repository.value}:{})}):undefined;
 if(!valid()||token!==generation)return;detail.value=next;if(next)repository.value=next.repository;
 }catch(e){if(valid()&&token===generation){error.value=safe(e instanceof Error?e.message:e);detail.value=undefined;}}finally{if(valid()&&token===generation)loading.value=false;}}
function reset(){generation++;request.invalidate();catalog.value=undefined;detail.value=undefined;projectId.value='';repository.value='';query.value='';error.value='';loading.value=false;skillView.value='skills';logs.value=false;people.value=false;audit.value=false;manager.value=undefined;}
async function chooseProject(id:string){if(projectId.value===id)return;generation++;request.invalidate();projectId.value=id;repository.value='';detail.value=undefined;query.value='';error.value='';manager.value=undefined;await nextTick();if(scroll.value)scroll.value.scrollTop=0;void refresh(false);}
function changeRepository(value:unknown){generation++;request.invalidate();repository.value=String(value);detail.value=undefined;query.value='';manager.value=undefined;void refresh(false);}
function jump(){try{const {agentId,sessionKey}=target.value;if(!agentId||!sessionKey)throw Error('请选择该 Agent 的会话后打开 Worker 项目');openWorkerProject({agentId,sessionKey,projectId:projectId.value});}catch(e){error.value=safe(e instanceof Error?e.message:e);}}
function openManager(id?:string,action?:string){managerOrigin=id;manager.value={...(id?{id}:{}),...(action?{action}:{}),sequence:++managerSequence};}
const groupName=(t:{chatId?:string})=>{const key='agent:'+agentId.value+':feishu:group:'+t.chatId,row=context.value.host.sessions.rows?.find(r=>r.key===key);return [row?.label,row?.displayName].find(n=>typeof n==='string'&&n.trim()&&!n.includes(t.chatId??''))?.trim()??'群名称未获取';};
function managerFocus(){const id=managerOrigin;return id?Array.from(root.value?.querySelectorAll<HTMLElement>('[data-task-id]')??[]).find(n=>n.dataset.taskId===id||n.dataset.taskId==='scheduled-request:'+id)??null:Array.from(root.value?.querySelectorAll<HTMLElement>('button')??[]).find(n=>n.textContent==='管理定时任务')??null;}
const auditInvoke=(action:string,payload:Record<string,unknown>)=>request.invoke<AuditPage>(action,payload);
const auditFeature=computed(()=>mode.value==='tasks'?'schedules':mode.value==='logs'?'logs':'skills');
watch(scope,()=>{reset();void refresh();},{flush:'sync'});
const stopNavigation=subscribeWorkerNavigation(()=>{navigationAvailable.value=canOpenWorkerProject();});
defineExpose({refreshFromUpdate:()=>{if(context.value!==lastRefreshContext)void refresh();}});
onMounted(()=>void refresh());onBeforeUnmount(()=>{generation++;stopNavigation();});
</script>
<template><section ref="root" class="ar-panel" :data-management-section="mode" aria-label="Agent Repo 项目、技能与子代理"><header class="ar-panel-header" :class="{'ar-section-heading':!!mode}"><div v-if="mode"><h2>{{mode==='tasks'?'定时任务':'项目与技能'}}</h2><p class="ar-description">{{mode==='tasks'?'查看仓库同步和 OpenClaw 联动群任务的计划、状态与运行记录。':'查看共享及项目技能，管理关联 CLI 与子代理。'}}</p></div><strong v-else>项目、技能与子代理</strong><div class="ar-panel-actions"><Button variant="outline" :disabled="loading||!context.host.connection.canRead||!agentId" @click="refresh()">{{loading?'扫描中…':mode==='tasks'?'刷新任务':'刷新扫描'}}</Button><Button variant="ghost" :disabled="!context.host.connection.canRead||!agentId" @click="audit=true">查看审计</Button><template v-if="!mode&&context.host.connection.canRead&&agentId"><Button variant="ghost" data-repository-logs aria-haspopup="dialog" @click="logs=true">日志</Button><Button variant="ghost" aria-haspopup="dialog" @click="people=true">人员资料</Button></template></div></header>
<template v-if="context.presented"><p v-if="!context.host.connection.canRead">需要 operator.read 权限才能查看。</p><p v-else-if="!agentId">请先选择一个 Agent。</p><template v-else><p v-if="!mode" class="ar-meta">{{safe('当前 Agent · '+agentId)}}</p><p v-if="error" class="ar-error" role="alert">{{error}}</p><p v-if="!catalog" class="ar-muted">{{loading?mode==='tasks'?'正在读取定时任务…':'正在读取项目、技能与子代理…':'尚未取得项目登记'}}</p><template v-else><template v-if="mode!=='tasks'"><p v-if="!catalog.registrationCommitted" class="ar-warning">项目登记存在未提交变化；当前展示仅供检查，执行前须提交并复核。</p><Tabs :model-value="projectId" :items="tabs" label="仓库与项目" list-class="ar-project-tabs ar-tabs" activation-mode="manual" @update:model-value="chooseProject"><template #default><div ref="scroll" class="ar-scroll"><template v-if="!projectId"><template v-if="mode!=='projects'"><h2>{{safe(catalog.root?.split('/').filter(Boolean).at(-1)??'Agent Repo')}}</h2><code class="ar-path">{{safe(catalog.root??'skills/')}}</code><p class="ar-meta">此 Agent 的所有项目共享</p><p v-if="!catalog.projects.length" class="ar-muted">尚未登记项目。当前仍可查看技能和子代理。</p></template></template><p v-else-if="!detail" class="ar-muted">{{loading?'正在读取当前项目内容…':'当前项目内容尚未读取，请重试或选择其他 Tab。'}}</p>
<template v-if="detail"><div class="ar-project-heading"><h2>{{safe(detail.name)}}</h2><div class="ar-project-actions"><Button variant="link" :disabled="!target.sessionKey||!navigationAvailable" :title="!target.sessionKey?'先选择该 Agent 的会话':!navigationAvailable?'需要加载配套 Agent Worker UI':'打开当前会话中此项目的 Worker 任务'" @click="jump">查看 Worker 项目任务 ↗</Button><WorkspacePool :project-id="projectId" :invoke="request.invoke" :can-write="()=>context.host.connection.canWrite===true" :safe="safe"/></div></div><code class="ar-path">{{safe(detail.cwd)}}</code><NativeSelect :model-value="repository" aria-label="当前仓库范围" @update:model-value="changeRepository"><option v-for="row in detail.scopes" :key="row.repository" :value="row.repository">{{safe(row.label)}}</option></NativeSelect><p class="ar-meta">{{safe('当前范围 · '+detail.repository+' · 共 '+detail.effectiveSkillCount+' 个候选技能')}}</p><p class="ar-meta"><span>{{!inherited||inherited.state==='unavailable'?'继承的技能暂不可读取 · ':'继承 '+inherited.skills.length+' 个技能 · '}}</span><Button class="ar-text-action" variant="link" @click="chooseProject('')">查看 Agent Repo</Button></p><p v-if="inherited?.warning" class="ar-warning">{{safe(inherited.warning)}}</p><p v-if="inherited?.state==='dirty'" class="ar-warning">继承的技能有未提交变化，当前使用已提交版本。</p><p v-if="inheritedSubagents" class="ar-meta">{{inheritedSubagents.state==='unavailable'?'共享子代理暂不可读取':safe('目录索引 · '+detail.candidateSubagentCount+' 个子代理定义 · 共享 '+inheritedSubagents.subagents.length+' 个，见 Agent Repo')}}</p><p class="ar-meta">{{safe('本地仓库状态 · '+detail.inspection.git.state+(detail.inspection.git.branch?' · '+detail.inspection.git.branch:'')+(detail.inspection.git.dirty?' · 有本地修改':'')+(detail.inspection.git.branchMatches===false?' · 分支不匹配':'')+(detail.inspection.git.remoteMatches===false?' · origin 不匹配':''))}}</p><p class="ar-muted">候选索引不代表会话已加载技能正文；Main 和 Worker 仍需选定范围、准备版本并按任务读取。</p></template>
<template v-if="!projectId||detail"><SkillMaintenance ref="maintenance" :agent-id="agentId" :sources="sources" :scope-key="projectId+':'+repository" @query="query=$event" @view="skillView=$event"/><SubagentsView v-show="skillView!=='cli'" :sources="subagentSources" :query="query" :safe="safe"/></template><TaskDirectory v-if="catalog.scheduledTasks" :tasks="catalog.scheduledTasks" :agent-id="agentId" :available="catalog.scheduledRequestsAvailable!==false" :invoke="request.invoke" :safe="safe" :on-manage="openManager"/><p class="ar-muted">更新时间来自技能目录最后一次 Git 提交，包含正文、引用及资源变化；子代理更新时间来自定义文件及关联配置最近一次提交；刷新扫描不执行 fetch、pull 或加载。</p><p class="ar-meta">{{safe('扫描于 '+date(detail?.scannedAt??catalog.scannedAt))}}</p></div></template></Tabs></template><TaskDirectory v-else :tasks="catalog.scheduledTasks??[]" :agent-id="agentId" full :available="catalog.scheduledRequestsAvailable!==false" :invoke="request.invoke" :safe="safe" :on-manage="openManager"/></template></template></template>
<ScheduleManager v-if="manager" :key="manager.sequence" :invoke="request.invoke" :can-write="()=>context.host.connection.canWrite===true" :safe="safe" :group-name="groupName" :initial-task-id="manager.id" :initial-action="manager.action" :on-close="()=>manager=undefined" :on-changed="()=>refresh()" :return-focus="managerFocus"/>
<PeopleDialog v-if="people" :options="{invoke:request.invoke,canWrite:()=>context.host.connection.canWrite===true,safe,isGroup:sourceIsGroup,onClose:()=>people=false}"/>
<Dialog size="wide" v-model:open="audit" title="修改审计"><AuditView v-if="audit" :invoke="auditInvoke" :safe="safe" :feature="auditFeature"/></Dialog>
<Dialog size="reader" v-model:open="logs" title="日志" description="统一查看插件与 Worker 日志；实时调试默认关闭。" content-class="ar-log-dialog"><LogsView v-if="logs" :key="agentId+':'+target.sessionKey" :agent-id="agentId" :session-key="target.sessionKey" embedded/></Dialog>
</section></template>
